<?php $title='RFID Attendance'; require_once __DIR__.'/../partials/header.php'; $db=new Database();$c=$db->getConnection();$employees=$c->query("SELECT id,employee_code,name FROM employees WHERE status='active' ORDER BY name")->fetch_all(MYSQLI_ASSOC);$m=new RfidAttendance($c);$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf($_POST['csrf_token']??null);$m->registerCard((int)$_POST['employee_id'],(string)$_POST['uid'],(string)($_POST['card_type']??'MIFARE'));redirect('rfid.php');}catch(Throwable $e){$error=$e->getMessage();}}$cards=$m->cards();?><section class="panel"><div class="panel-head"><h2>Assign RFID Card</h2><a class="btn btn-primary" href="../kiosk/" target="_blank">Open Kiosk</a></div><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="field"><label>Employee</label><select class="select" name="employee_id" required><?php foreach($employees as $r):?><option value="<?=$r['id']?>"><?=e($r['employee_code'].' — '.$r['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Card UID</label><input class="input" name="uid" placeholder="Tap card / enter UID" required></div><div class="field"><label>Card Type</label><select class="select" name="card_type"><option>MIFARE</option><option>NTAG</option><option>NFC</option></select></div><div><button class="btn btn-primary">Assign / Replace Card</button></div></form></section><section class="panel"><div class="panel-head"><h2>Registered Cards</h2></div><div class="table-wrap"><table class="table"><thead><tr><th>Employee</th><th>UID</th><th>Type</th><th>Status</th><th>Issued</th></tr></thead><tbody><?php foreach($cards as $r):?><tr><td><?=e($r['employee_code'].' — '.$r['name'])?></td><td><code><?=e($r['uid'])?></code></td><td><?=e($r['card_type'])?></td><td><span class="badge <?=e($r['status'])?>"><?=e($r['status'])?></span></td><td><?=e($r['issued_at'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php require_once __DIR__.'/../partials/footer.php';
